// Resumen de las ventas de ayer. Usa la zona horaria de n8n (Settings > Timezone).
const ayer = $now.minus({ days: 1 });
const ayerISO = ayer.toFormat('yyyy-MM-dd');

// Acepta fechas AAAA-MM-DD y DD/MM/AAAA
function aISO(valor) {
  const texto = String(valor ?? '').trim();
  const dma = texto.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (dma) return dma[3] + '-' + dma[2].padStart(2, '0') + '-' + dma[1].padStart(2, '0');
  return texto.slice(0, 10);
}

const ventas = $input.all()
  .map((item) => item.json)
  .filter((fila) => aISO(fila.Fecha) === ayerISO);

const total = ventas.reduce((suma, fila) => suma + (Number(fila.Total) || 0), 0);

// Producto más vendido (por número de ventas)
const porProducto = {};
for (const fila of ventas) {
  const producto = String(fila.Producto || 'Sin producto');
  porProducto[producto] = (porProducto[producto] || 0) + 1;
}
const [masVendido, veces] = Object.entries(porProducto).sort((a, b) => b[1] - a[1])[0] ?? ['', 0];

const dinero = new Intl.NumberFormat('es', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(total);
const dia = ayer.setLocale('es').toFormat("cccc d 'de' LLLL");

const asunto = ventas.length === 0
  ? 'Reporte de ventas: sin ventas el ' + dia
  : 'Reporte de ventas del ' + dia + ': ' + ventas.length + ' ventas, ' + dinero;

const cuerpo = ventas.length === 0
  ? 'Ayer (' + dia + ') no se registraron ventas en la hoja.\n\nSi esperabas ventas, revisa que la columna Fecha tenga el formato AAAA-MM-DD o DD/MM/AAAA.'
  : [
      'Resumen de ventas del ' + dia + ':',
      '',
      'Ventas: ' + ventas.length,
      'Total: ' + dinero,
      'Producto más vendido: ' + masVendido + ' (' + veces + (veces === 1 ? ' venta)' : ' ventas)'),
    ].join('\n');

return [{ json: { asunto, cuerpo, ventas: ventas.length, total } }];
